package com.loanops.fincompass.opportunity;
import com.loanops.fincompass.twin.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import static com.loanops.fincompass.opportunity.OpportunityModels.*;import static com.loanops.fincompass.twin.TwinModels.*;import static org.assertj.core.api.Assertions.*;
class OpportunityEngineTest {private final OpportunityEngine engine=new OpportunityEngine();private final Policy policy=Policy.defaults();
 @Test void healthySingleSnapshotAndMissingProductsProduceNoEvent(){var current=snapshot("66000000","30000000","600000","4800000",List.of());assertThat(engine.evaluate(current,List.of(current),null,List.of(),policy)).isEmpty();}
 @Test void debtThresholdIsStrictAndConfigurationDriven(){var boundary=snapshot("66000000","30000000","2200000","6400000",List.of());assertThat(boundary.result().metrics().get("DEBT_SERVICE_BURDEN").value()).isEqualByComparingTo(".4");assertThat(engine.evaluate(boundary,List.of(boundary),null,List.of(),policy)).noneMatch(e->e.type()==Type.DEBT_BURDEN_WARNING);var over=snapshot("66000000","30000000","2200001","6400001",List.of());assertThat(engine.evaluate(over,List.of(over),null,List.of(),policy)).anyMatch(e->e.type()==Type.DEBT_BURDEN_WARNING);}
 @Test void validatedHistoricalImprovementCreatesRateReview(){var old=snapshot("60000000","30000000","600000","4800000",List.of());var current=snapshot("66000000","30000000","600000","4800000",List.of());assertThat(engine.evaluate(current,List.of(old,current),null,List.of(),policy)).extracting(Draft::type).containsExactly(Type.RATE_REVIEW);}
 @Test void staleOrIncompleteStateDoesNotCreateEvents(){var stale=snapshot("66000000","30000000","600000","4800000",List.of("STALE_BALANCE"));assertThat(engine.evaluate(stale,List.of(stale),null,List.of(),policy)).isEmpty();var incomplete=new Snapshot(stale.financialSnapshotId(),stale.financialUserId(),stale.asOf(),stale.createdAt(),"INCOMPLETE",stale.calculationRuleVersion(),stale.inputFingerprint(),stale.input(),stale.result());assertThat(engine.evaluate(incomplete,List.of(incomplete),null,List.of(),policy)).isEmpty();}
 private Snapshot snapshot(String income,String liability,String debt,String inflow,List<String>warnings){Instant at=Instant.parse("2026-09-21T10:00:00Z");var facts=List.of(fact("EXISTING_LOAN_BALANCE",liability,at),fact("SCHEDULED_MONTHLY_DEBT_SERVICE",debt,at),fact("MONTHLY_FIXED_OBLIGATION","200000",at),fact("MONTHLY_ESSENTIAL_EXPENSE","2200000",at),fact("EXISTING_LOAN_ANNUAL_RATE",".061",at));var input=new Input(id(income+liability+debt),at,List.of(),facts,new BigDecimal("120000000"),new BigDecimal(income),List.of(new ClassifiedTransaction(id("income"),new BigDecimal(inflow),"CREDIT",Category.INCOME),new ClassifiedTransaction(id("living"),new BigDecimal("2800000"),"DEBIT",Category.LIVING_EXPENSE),new ClassifiedTransaction(id("debt"),new BigDecimal(debt),"DEBIT",Category.DEBT_SERVICE)),1,true,true,true,warnings);var calc=new TwinCalculator();return new Snapshot(id("s"+income+liability+debt),input.financialUserId(),at,at,"COMPLETE",TwinCalculator.RULE_VERSION,calc.fingerprint(input),input,calc.calculate(input));}
 private Fact fact(String k,String v,Instant at){return new Fact(id(k+v),k,new BigDecimal(v),"USER_INPUT","DEMO_REPLAY",at,"KRW","test");}private UUID id(String v){return UUID.nameUUIDFromBytes(v.getBytes(StandardCharsets.UTF_8));}}
